// Killedar service worker. Generated by scripts/build.ts — edit this template, not dist/sw.js.
// Strategy:
//   app shell, fort data, audio  → precached at install, cache-first (works in airplane mode)
//   WebLLM module from the CDN   → stale-while-revalidate (cached on first online visit)
//   model weights                → left to WebLLM, which stores them in its own Cache Storage
//   prediction API               → network only; the app falls back to the rule of thumb

const VERSION = "__VERSION__";
const PRECACHE = __PRECACHE__;
const SHELL = `killedar-shell-${VERSION}`;
const RUNTIME = "killedar-cdn";
const CDN_HOSTS = ["esm.run", "cdn.jsdelivr.net"];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(SHELL)
      .then((cache) => cache.addAll(PRECACHE))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith("killedar-shell-") && k !== SHELL).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);

  if (url.origin === self.location.origin) {
    event.respondWith(shellFirst(req));
  } else if (CDN_HOSTS.includes(url.hostname)) {
    event.respondWith(staleWhileRevalidate(req));
  }
  // everything else (API, model weights) goes straight to the network
});

async function shellFirst(req) {
  const cache = await caches.open(SHELL);
  const hit = await cache.match(req, { ignoreSearch: true });
  if (hit) return hit;
  try {
    return await fetch(req);
  } catch (err) {
    if (req.mode === "navigate") {
      const index = await cache.match("./index.html");
      if (index) return index;
    }
    throw err;
  }
}

async function staleWhileRevalidate(req) {
  const cache = await caches.open(RUNTIME);
  const hit = await cache.match(req);
  const fresh = fetch(req)
    .then((res) => {
      if (res.ok) cache.put(req, res.clone());
      return res;
    })
    .catch(() => undefined);
  return hit ?? (await fresh) ?? Response.error();
}
